// Authentication utility functions

// Initialize users database in localStorage
const initializeUsers = () => {
  if (!localStorage.getItem('users')) {
    const defaultUsers = [
      {
        id: 1,
        name: 'Admin User',
        email: 'admin@kartavya.com',
        password: 'admin123',
        role: 'admin',
        location: 'Mumbai, Maharashtra',
        joinDate: new Date().toISOString(),
        stats: {
          totalReports: 0,
          resolvedIssues: 0,
          points: 0,
          rank: 0
        }
      }
    ];
    localStorage.setItem('users', JSON.stringify(defaultUsers));
  }
};

// Get all users
export const getUsers = () => {
  initializeUsers();
  return JSON.parse(localStorage.getItem('users') || '[]');
};

// Register new user
export const registerUser = (userData) => {
  const users = getUsers();
  
  // Check if email already exists
  if (users.find(u => u.email === userData.email)) {
    throw new Error('Email already registered');
  }

  const newUser = {
    id: users.length + 1,
    name: userData.name,
    email: userData.email,
    password: userData.password,
    role: 'user',
    location: userData.location,
    joinDate: new Date().toISOString(),
    stats: {
      totalReports: 0,
      resolvedIssues: 0,
      points: 0,
      rank: users.filter(u => u.role === 'user').length + 1
    }
  };

  users.push(newUser);
  localStorage.setItem('users', JSON.stringify(users));
  return newUser;
};

// Login user
export const loginUser = (email, password, role) => {
  const users = getUsers();
  const user = users.find(u => 
    u.email === email && 
    u.password === password && 
    u.role === role
  );

  if (!user) {
    throw new Error('Invalid credentials or role');
  }

  // Store current user
  const userSession = {
    id: user.id,
    name: user.name,
    email: user.email,
    role: user.role,
    location: user.location,
    joinDate: user.joinDate,
    stats: user.stats
  };

  localStorage.setItem('currentUser', JSON.stringify(userSession));
  localStorage.setItem('isAuthenticated', 'true');
  
  return userSession;
};

// Get current logged-in user
export const getCurrentUser = () => {
  const userStr = localStorage.getItem('currentUser');
  return userStr ? JSON.parse(userStr) : null;
};

// Logout
export const logoutUser = () => {
  localStorage.removeItem('currentUser');
  localStorage.removeItem('isAuthenticated');
};

// Check if user is authenticated
export const isAuthenticated = () => {
  return localStorage.getItem('isAuthenticated') === 'true';
};

// Check if current user is admin
export const isAdmin = () => {
  const user = getCurrentUser();
  return user && user.role === 'admin';
};

// Update user stats
export const updateUserStats = (updates) => {
  const currentUser = getCurrentUser();
  if (!currentUser) return;

  const users = getUsers();
  const userIndex = users.findIndex(u => u.id === currentUser.id);
  
  if (userIndex !== -1) {
    users[userIndex].stats = {
      ...users[userIndex].stats,
      ...updates
    };
    
    localStorage.setItem('users', JSON.stringify(users));
    
    // Update current user session
    currentUser.stats = users[userIndex].stats;
    localStorage.setItem('currentUser', JSON.stringify(currentUser));
  }
};
